31	/**
32	 * Simple JavaBean domain object representing an owner.
33	 *
34	 * @author Ken Krebs
35	 * @author Juergen Hoeller
36	 * @author Sam Brannen
37	 * @author Michael Isvy
38	 */
39	@Entity
40	@Table(name = "owners")
41	public class Owner extends Person {
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "city")
47	    @NotEmpty
48	    private String city;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    private String email;
57	
58	    @Column(name = "registration_date", columnDefinition = "DATE")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "birth_date", columnDefinition = "DATE")
62	    private LocalDate birthDate;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "household_id")
68	    private String householdId;
69	
70	    @Column(name = "namesake_count")
71	    private Integer namesakeCount;
72	
73	    @Column(name = "household_size")
74	    private Integer householdSize;
75	
76	    @Column(name = "postcode")
77	    private String postcode;
78	
79	    @Column(name = "bulk_signup_warning")
80	    private Boolean bulkSignupWarning;
81	
82	    @Column(name = "possible_duplicate")
83	    private Boolean possibleDuplicate;
84	
85	    @Column(name = "possible_duplicate_of")
86	    private Integer possibleDuplicateOf;
87	
88	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
89	    private Set<Pet> pets;
90	
91	    /**
92	     * Fixed city-to-region table used to derive {@link #getLocality() locality} when the postcode
93	     * is absent or in no known range. Any city not listed derives the locality {@code 'UNKNOWN'}.
94	     */
95	    private static final Map<String, String> CITY_REGION = Map.of(
96	        "Sydney", "NSW",
97	        "Melbourne", "VIC",
98	        "Brisbane", "QLD");
99	
100	    /**
101	     * Inclusive 4-digit postcode range per region, used to derive {@link #getLocality() locality}
102	     * from the postcode in preference to the city: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
103	     */
104	    private static final Map<String, int[]> REGION_POSTCODE = Map.of(
105	        "NSW", new int[] {2000, 2099},
106	        "VIC", new int[] {3000, 3099},
107	        "QLD", new int[] {4000, 4099});
108	
109	    public String getAddress() {
110	        return this.address;
111	    }
112	
113	    public void setAddress(String address) {
114	        this.address = address;
115	    }
116	
117	    public String getCity() {
118	        return this.city;
119	    }
120	
121	    public void setCity(String city) {
122	        this.city = city;
123	    }
124	
125	    public String getTelephone() {
126	        return this.telephone;
127	    }
128	
129	    public void setTelephone(String telephone) {
130	        this.telephone = telephone;
131	    }
132	
133	    /**
134	     * Known E.164 country codes whose national-number length is fixed, used to split the stored
135	     * telephone into its country code and national digits for display: Australia ({@code '61'}) and
136	     * the North American Numbering Plan ({@code '1'}). A number whose country code is not listed is
137	     * split by taking its leading digit as the (minimal) country code.
138	     */
139	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
140	
141	    /**
142	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans: the country code, a
143	     * single space, then the national digits grouped in threes from the left (e.g. the stored
144	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw telephone itself stays in
145	     * E.164 form. Returns the stored value unchanged when it is absent or not a {@code '+'}-prefixed
146	     * digit string.
147	     *
148	     * @return the human-readable telephone, or the stored value when it cannot be formatted
149	     */
150	    public String getTelephoneDisplay() {
151	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
152	            return this.telephone;
153	        }
154	        String digits = this.telephone.substring(1);
155	        String countryCode = extractCountryCode(digits);
156	        String national = digits.substring(countryCode.length());
157	        StringBuilder display = new StringBuilder("+").append(countryCode);
158	        for (int i = 0; i < national.length(); i += 3) {
159	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
160	        }
161	        return display.toString();
162	    }
163	
164	    /**
165	     * Splits the country code off an E.164 digit string (country code followed by national digits,
166	     * without the leading {@code '+'}). A country code listed in {@link #COUNTRY_NATIONAL_LENGTH}
167	     * whose required national-number length matches the remaining digits is preferred; failing that,
168	     * the leading digit is used as the country code.
169	     *
170	     * @param digits the E.164 digits without the leading {@code '+'}
171	     * @return the country-code portion of {@code digits}
172	     */
173	    private static String extractCountryCode(String digits) {
174	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
175	            String code = entry.getKey();
176	            if (digits.startsWith(code) && digits.length() - code.length() == entry.getValue()) {
177	                return code;
178	            }
179	        }
180	        return digits.substring(0, 1);
181	    }
182	
183	    public String getEmail() {
184	        return this.email;
185	    }
186	
187	    public void setEmail(String email) {
188	        this.email = email;
189	    }
190	
191	    public LocalDate getRegistrationDate() {
192	        return this.registrationDate;
193	    }
194	
195	    public void setRegistrationDate(LocalDate registrationDate) {
196	        this.registrationDate = registrationDate;
197	    }
198	
199	    public LocalDate getBirthDate() {
200	        return this.birthDate;
201	    }
202	
203	    public void setBirthDate(LocalDate birthDate) {
204	        this.birthDate = birthDate;
205	    }
206	
207	    /**
208	     * The owner's age band, derived from the {@link #getBirthDate() birth date} as at the owner's
209	     * {@link #getRegistrationDate() registration date}: {@code 'MINOR'} when under 18, {@code 'ADULT'}
210	     * when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is the number of whole years
211	     * elapsed from the birth date to the registration date (defaulting to the server's current date
212	     * when no registration date is set yet). Returns {@code null} when no birth date was supplied.
213	     *
214	     * @return the age band, or {@code null} when the birth date is absent
215	     */
216	    public String getAgeBand() {
217	        if (this.birthDate == null) {
218	            return null;
219	        }
220	        LocalDate asAt = this.registrationDate != null ? this.registrationDate : LocalDate.now();
221	        int years = Period.between(this.birthDate, asAt).getYears();
222	        if (years < 18) {
223	            return "MINOR";
224	        }
225	        if (years < 65) {
226	            return "ADULT";
227	        }
228	        return "SENIOR";
229	    }
230	
231	    public String getCustomerCode() {
232	        return this.customerCode;
233	    }
234	
235	    public void setCustomerCode(String customerCode) {
236	        this.customerCode = customerCode;
237	    }
238	
239	    /**
240	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
241	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived
242	     * from the owner's own customer code and registration date; {@code null} when either is absent.
243	     *
244	     * @return the membership number, or {@code null} when it cannot be derived
245	     */
246	    public String getMembershipNumber() {
247	        if (this.customerCode == null || this.registrationDate == null) {
248	            return null;
249	        }
250	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
251	    }
252	
253	    /**
254	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
255	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
256	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
257	     *
258	     * @return the Luhn check digit, or {@code null} when the customer code is absent
259	     */
260	    public Integer getCheckDigit() {
261	        if (this.customerCode == null) {
262	            return null;
263	        }
264	        int sum = 0;
265	        boolean dbl = true;
266	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
267	            char c = this.customerCode.charAt(i);
268	            if (c < '0' || c > '9') {
269	                continue;
270	            }
271	            int d = c - '0';
272	            if (dbl) {
273	                d *= 2;
274	                if (d > 9) {
275	                    d -= 9;
276	                }
277	            }
278	            sum += d;
279	            dbl = !dbl;
280	        }
281	        return (10 - (sum % 10)) % 10;
282	    }
283	
284	    /**
285	     * The owner's numeric membership level, derived from the values frozen at create time. It starts
286	     * at 1, gains 1 when an email address is present, gains 1 when the owner has no namesakes
287	     * ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
288	     *
289	     * @return the membership level, an integer from 1 to 3
290	     */
291	    public Integer getMembershipLevel() {
292	        int level = 1;
293	        boolean hasEmail = this.email != null && !this.email.isBlank();
294	        if (hasEmail) {
295	            level++;
296	        }
297	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
298	        if (hasNoNamesakes) {
299	            level++;
300	        }
301	        return Math.min(level, 3);
302	    }
303	
304	    /**
305	     * The owner's locality, the canonical region string. Once the owner has a
306	     * {@link #getCustomerCode() customer code} the locality is the {@code <REGION>} component of that
307	     * code (the text before the first {@code '-'}), so the locality and the identity share a single
308	     * source of truth. Before the customer code is assigned (for example while a create is still
309	     * validating the postcode) it falls back to the region the code will be built from: the
310	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
311	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
312	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
313	     *
314	     * @return the canonical region string, or {@code 'UNKNOWN'}
315	     */
316	    public String getLocality() {
317	        if (this.customerCode != null) {
318	            int dash = this.customerCode.indexOf('-');
319	            return dash >= 0 ? this.customerCode.substring(0, dash) : this.customerCode;
320	        }
321	        return deriveRegion();
322	    }
323	
324	    /**
325	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
326	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
327	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
328	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
329	     * the same region for known cities but disambiguates cities that share a name.
330	     *
331	     * @return the canonical region string, or {@code 'UNKNOWN'}
332	     */
333	    private String deriveRegion() {
334	        String region = regionFromPostcode();
335	        if (region != null) {
336	            return region;
337	        }
338	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
339	    }
340	
341	    /**
342	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
343	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
344	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
345	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
346	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
347	     * owner's region, telephone and last name. Call this once at create time and store the result via
348	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
349	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
350	     *
351	     * @return the assembled customer code
352	     */
353	    public String buildCustomerCode() {
354	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
355	    }
356	
357	    /**
358	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
359	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
360	     *
361	     * @param value the value to hash
362	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
363	     */
364	    private static String sha256Hex8(String value) {
365	        try {
366	            byte[] digest = MessageDigest.getInstance("SHA-256")
367	                .digest(value.getBytes(StandardCharsets.UTF_8));
368	            StringBuilder hex = new StringBuilder(8);
369	            for (int i = 0; i < 4; i++) {
370	                hex.append(String.format("%02X", digest[i]));
371	            }
372	            return hex.toString();
373	        }
374	        catch (NoSuchAlgorithmException e) {
375	            throw new IllegalStateException("SHA-256 algorithm not available", e);
376	        }
377	    }
378	
379	    /**
380	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
381	     * absent, not a 4-digit number, or in no known range.
382	     *
383	     * @return the matching region, or {@code null}
384	     */
385	    private String regionFromPostcode() {
386	        if (this.postcode == null) {
387	            return null;
388	        }
389	        int value;
390	        try {
391	            value = Integer.parseInt(this.postcode.trim());
392	        }
393	        catch (NumberFormatException ex) {
394	            return null;
395	        }
396	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
397	            int[] range = entry.getValue();
398	            if (value >= range[0] && value <= range[1]) {
399	                return entry.getKey();
400	            }
401	        }
402	        return null;
403	    }
404	
405	    /**
406	     * The owner's preferred contact channel, derived from the owner's details. Returns
407	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
408	     *
409	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
410	     */
411	    public String getContactPreference() {
412	        boolean hasEmail = this.email != null && !this.email.isBlank();
413	        return hasEmail ? "EMAIL" : "PHONE";
414	    }
415	
416	    /**
417	     * The owner's identity key, the single derived value used for duplicate detection. It is the
418	     * owner's normalized telephone, email (empty when absent) and household id joined with
419	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
420	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
421	     * are equal, so two members of the same household with different telephones differ here and are
422	     * both allowed.
423	     *
424	     * @return the derived identity key
425	     */
426	    public String getIdentityKey() {
427	        return (this.telephone == null ? "" : this.telephone) + "|"
428	            + (this.email == null ? "" : this.email) + "|"
429	            + (this.householdId == null ? "" : this.householdId);
430	    }
431	
432	    public String getHouseholdId() {
433	        return this.householdId;
434	    }
435	
436	    public void setHouseholdId(String householdId) {
437	        this.householdId = householdId;
438	    }
439	
440	    public Integer getNamesakeCount() {
441	        return this.namesakeCount;
442	    }
443	
444	    public void setNamesakeCount(Integer namesakeCount) {
445	        this.namesakeCount = namesakeCount;
446	    }
447	
448	    public Integer getHouseholdSize() {
449	        return this.householdSize;
450	    }
451	
452	    public void setHouseholdSize(Integer householdSize) {
453	        this.householdSize = householdSize;
454	    }
455	
456	    public String getPostcode() {
457	        return this.postcode;
458	    }
459	
460	    public void setPostcode(String postcode) {
461	        this.postcode = postcode;
462	    }
463	
464	    public Boolean getBulkSignupWarning() {
465	        return this.bulkSignupWarning;
466	    }
467	
468	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
469	        this.bulkSignupWarning = bulkSignupWarning;
470	    }
471	
472	    public Boolean getPossibleDuplicate() {
473	        return this.possibleDuplicate;
474	    }
475	
476	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
477	        this.possibleDuplicate = possibleDuplicate;
478	    }
479	
480	    public Integer getPossibleDuplicateOf() {
481	        return this.possibleDuplicateOf;
482	    }
483	
484	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
485	        this.possibleDuplicateOf = possibleDuplicateOf;
486	    }
487	
488	    /**
489	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
490	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
491	     */
492	    @PrePersist
493	    void onCreate() {
494	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
495	    }
496	
497	    /**
498	     * Resolves the effective registration date and rolls it onto a business day. An absent
499	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
500	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
501	     * becomes the following Monday, while any weekday is returned unchanged.
502	     *
503	     * <p>This is the single definition of both the defaulting and the business-day roll, used
504	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
505	     * stamps the owner and by the create endpoint that counts owners per business day.
506	     *
507	     * @param supplied the registration date from the request, or {@code null} when none was supplied
508	     * @return the effective registration date, guaranteed to fall on a business day
509	     */
510	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
511	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
512	        return switch (effective.getDayOfWeek()) {
513	            case SATURDAY -> effective.plusDays(2);
514	            case SUNDAY -> effective.plusDays(1);
515	            default -> effective;
516	        };
517	    }
518	
519	    protected Set<Pet> getPetsInternal() {
520	        if (this.pets == null) {
521	            this.pets = new HashSet<>();
522	        }
523	        return this.pets;
524	    }
525	
526	    protected void setPetsInternal(Set<Pet> pets) {
527	        this.pets = pets;
528	    }
529	
530	    public List<Pet> getPets() {
531	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
532	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
533	        return Collections.unmodifiableList(sortedPets);
534	    }
535	
536	    public void setPets(List<Pet> pets) {
537	        this.pets = new HashSet<>(pets);
538	    }
539	
540	    public void addPet(Pet pet) {
541	        getPetsInternal().add(pet);
542	        pet.setOwner(this);
543	    }
544	
545	    /**
546	     * Return the Pet with the given name, or null if none found for this Owner.
547	     *
548	     * @param name to test
549	     * @return true if pet name is already in use
550	     */
551	    public Pet getPet(String name) {
552	        return getPet(name, false);
553	    }
554	
555	    /**
556	     * Return the Pet with the given name, or null if none found for this Owner.
557	     *
558	     * @param name to test
559	     * @return true if pet name is already in use
560	     */
561	    public Pet getPet(String name, boolean ignoreNew) {
562	        name = name.toLowerCase();
563	        for (Pet pet : getPetsInternal()) {
564	            if (!ignoreNew || !pet.isNew()) {
565	                String compName = pet.getName();
566	                compName = compName.toLowerCase();
567	                if (compName.equals(name)) {
568	                    return pet;
569	                }
570	            }
571	        }
572	        return null;
573	    }
574	
575	    public Pet getPet(Integer petId) {
576	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
577	    }
578	
579	    @Override
580	    public String toString() {
581	        return new ToStringCreator(this)
582	
583	            .append("id", this.getId())
584	            .append("new", this.isNew())
585	            .append("lastName", this.getLastName())
586	            .append("firstName", this.getFirstName())
587	            .append("address", this.address)
588	            .append("city", this.city)
589	            .append("telephone", this.telephone)
590	            .toString();
591	    }
592	}
